import{_ as e,c as t,o as s,af as p}from"./chunks/framework.BKeRpnBD.js";const d=JSON.parse('{"title":"爻辰第十五","description":"杭氏易学 - 爻辰第十五","frontmatter":{"title":"爻辰第十五","description":"杭氏易学 - 爻辰第十五"},"headers":[],"relativePath":"zh/classics/hangshi/016.md","filePath":"zh/classics/hangshi/016.md"}'),r={name:"zh/classics/hangshi/016.md"};function i(n,a,c,_,o,l){return s(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="爻辰第十五" tabindex="-1">爻辰第十五 <a class="header-anchor" href="#爻辰第十五" aria-label="Permalink to “爻辰第十五”">​</a></h1><p>先天八卦，以阴阳升降，应日月之晦朔弦望，于是乎有纳甲。因而重之，为六十四卦。卦有六爻，卦纳干而爻纳支，于是乎有爻辰。辰者天度十二宫之次舍。而地支之十二，与天度相应者也。汉人言爻辰者，有郑氏，有京氏，其说不同。郑氏以乾阳坤阴，十二爻顺逆交错，以应十二月。而又以六十四卦之爻，合乾坤，分二十八宿之度数、星象合卦爻之象，以释经。其书久佚，仅自《李氏集解》，及各经注疏采集其说，但存其梗概而已。有清戴氏棠，据《甘石星经》、《开元占经》等书，按六十四卦之《彖》、《象》、《系辞》，有以星象名义，或形似相类，援郑例而补之，名《爻辰补》。然于经义象数，均未有当，无足采焉。</p><p>京氏纳辰为古今术家所遵用，证之于《彖》、《象》十翼，多能相合。有与经义相发明，为经学家所不能道者。始知黄帝五甲六子三元九宫，实探阴阴造化之秘，明天人之际。以济世利民者，固不仅卜筮之用也。康成生于汉季，施、孟、梁丘之《易》，已多失传。独费氏，因其说简约而独存。康成亦有所不足，故采取残缺之纬书，兼及五行律历星象，以释卦爻，固费《易》之所无，或亦三家之遗义也。惜其书又亡。致三代之《易》，不能尽见于今。犹幸京《易》虽亡，而八宫世应纳音纳甲之数，犹得贯通，得与《周易》相参证。乃学者又畏其繁琐，目为芜秽，必尽弃之，以自诩扩清之功，《易》道又何自明哉！</p><p>京氏六爻纳辰图</p><p>卦纳甲而爻纳辰，京氏以阳顺阴逆，交错为用。以乾坤为纲，六子分乾坤之爻，以次相推。仍以本宫为体，而六爻所纳之支，视其与本宫生克，以为亲疏远近利害之分。图如下：</p><p>阳卦纳阳，于阳支皆顺行。阴卦纳阴，于阴支皆逆行。乾内纳甲，外纳壬，支起子，子寅辰午申戌顺行。坤内纳乙，外纳癸，支起未，未巳卯丑亥酉逆行。阴阳交错，以相合为用者也。故乾生震，震为长子。长子代父纳庚，而六爻之支，与乾全同。子寅辰午申戌皆顺行也。坎中男，得乾中爻，乾内中寅，坎纳戊，故初爻自寅起，为戊寅，戊辰，戊午，戊申，戊戌，戊子也。艮少男，得乾之上爻。乾内三辰，艮纳丙，故初爻自辰起为丙辰，丙午，丙戌，丙子，丙寅也。坤生长女为巽，长女代母，而纳不起于丑，而起于未，与震袭乾不同者，此男女之别，阴阳之分。女以出为归，故自内出外。由四爻起未，五巳上卯，而反至初为丑二为亥三为酉也。离为中女，得坤中爻，故于外中五爻起未。兑为少女，得坤上爻，故于外上起未，皆未巳卯丑亥酉，与巽同例也。季彭山不知阴阳之别，妄改坤起乙丑。又有不分阴阳，不知本末，妄改乾为甲子，甲戌，甲午，甲寅，甲辰者，皆绝无意义。学者不可好奇喜新，为所误也。</p><p>六十四卦，八纯卦外，一世至六世，皆取本宫纳甲。见者为飞，不见者为伏。游魂归魂十六卦，不取本宫为伏。分举爻位如下：</p><p>晋以艮为伏，而取艮四爻者，以游魂仍为四爻变。而晋上之离，由剥上之艮变来者也。故不以本宫不以对宫而取艮。大有下卦之离，由晋下卦之坤变来者也。归魂为三爻，故取坤三。余卦仿此。</p><p>郑氏爻辰，亦以阴阳六爻，相间用事。乾辰子寅辰午申戌，其次与京氏同，而坤则为未酉亥丑卯巳与京氏异。盖阴阳虽间一位，而皆顺行。盖以十二律相生为据也。他卦分乾坤之爻，亦分乾坤之辰，不论纳甲。</p>',9)])])}const f=e(r,[["render",i]]);export{d as __pageData,f as default};
